package com.greenpulse.service;
import com.greenpulse.domain.*;
import com.greenpulse.repository.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.*;import java.math.*;import java.time.*;import java.util.*;
@Service
public class MlIntegrationService {
 private final ReadingService readings;private final BuildingRepository buildings;private final PredictionRepository predictions;private final AnomalyRepository anomalies;private final ReadingRepository readingRepository;private final CurrentUser current;private final RestTemplate http;private final String url;
 public MlIntegrationService(ReadingService readings,BuildingRepository buildings,PredictionRepository predictions,AnomalyRepository anomalies,ReadingRepository readingRepository,CurrentUser current,@Value("${greenpulse.ml-url}") String url){this.readings=readings;this.buildings=buildings;this.predictions=predictions;this.anomalies=anomalies;this.readingRepository=readingRepository;this.current=current;this.url=url.startsWith("http://")||url.startsWith("https://")?url:"http://"+url;var factory=new SimpleClientHttpRequestFactory();factory.setConnectTimeout(3000);factory.setReadTimeout(10000);this.http=new RestTemplate(factory);}
 private List<Map<String,Object>> data(Long building){return readings.byBuilding(building).stream().map(r->Map.<String,Object>of("reading_date",r.getReadingDate().toString(),"energy_consumed_kwh",r.getEnergyConsumedKwh())).toList();}
 @Transactional public Map<String,Object> predict(Long buildingId){var rows=data(buildingId);if(rows.size()<28)throw new IllegalArgumentException("At least 28 daily readings are required for predictions");var result=post("/predict",Map.of("readings",rows,"horizon_days",7,"model_name","random_forest"));var b=authorizedBuilding(buildingId);Object version=result.getOrDefault("model_version","1.0.0");Object name=result.getOrDefault("model_name","random_forest");Object list=result.get("predictions");if(list instanceof List<?> items)for(Object item:items)if(item instanceof Map<?,?> p){var prediction=new EnergyPrediction();prediction.setBuilding(b);prediction.setPredictionDate(LocalDate.parse(p.get("prediction_date").toString()));prediction.setPredictedKwh(new BigDecimal(p.get("predicted_kwh").toString()));prediction.setModelName(name.toString());prediction.setModelVersion(version.toString());predictions.save(prediction);}return result;}
 @Transactional public Map<String,Object> detect(Long buildingId){var rows=data(buildingId);if(rows.size()<10)throw new IllegalArgumentException("At least 10 readings are required for anomaly detection");var result=post("/detect-anomalies",Map.of("readings",rows));var b=authorizedBuilding(buildingId);Object list=result.get("anomalies");int stored=0;if(list instanceof List<?> items)for(Object item:items)if(item instanceof Map<?,?> a){var date=LocalDate.parse(a.get("reading_date").toString());var reading=readingRepository.range(buildingId,current.isSuper(current.get()),current.org(current.get()),date,date).stream().findFirst().orElse(null);if(reading==null||reading.getId()==null||anomalies.existsByReadingId(reading.getId()))continue;var alert=new AnomalyAlert();alert.setBuilding(b);alert.setReading(reading);alert.setAnomalyScore(new BigDecimal(a.get("anomaly_score").toString()));alert.setSeverity(a.get("severity").toString());alert.setDescription(a.get("explanation").toString());anomalies.save(alert);stored++;}return Map.of("storedAlerts",stored,"modelResponse",result);}
 public Map<String,Object> post(String path,Map<String,Object> body){try{var response=http.postForObject(url+path,body,Map.class);if(response==null)throw new IllegalStateException("ML service returned an empty response");return response;}catch(ResourceAccessException e){throw new IllegalStateException("ML service is unavailable or timed out");}catch(HttpClientErrorException e){throw new IllegalArgumentException("ML service rejected input: "+e.getResponseBodyAsString());}}
 public List<EnergyPrediction> predictionList(Long id){authorizedBuilding(id);return predictions.findByBuildingIdOrderByPredictionDateAsc(id);}
 public List<AnomalyAlert> anomalyList(){var u=current.get();return anomalies.scoped(current.isSuper(u),current.org(u));}
 public AnomalyAlert anomaly(Long id){var u=current.get();return anomalies.findScoped(id,current.isSuper(u),current.org(u)).orElseThrow(()->new NoSuchElementException("Anomaly not found"));}
 @Transactional public AnomalyAlert status(Long id,String status){if(!Set.of("OPEN","RESOLVED","DISMISSED").contains(status))throw new IllegalArgumentException("Status must be OPEN, RESOLVED, or DISMISSED");var a=anomaly(id);a.setStatus(status);a.setResolvedAt(status.equals("OPEN")?null:Instant.now());return anomalies.save(a);}
 private Building authorizedBuilding(Long id){var u=current.get();return buildings.findScoped(id,current.isSuper(u),current.org(u)).orElseThrow(()->new NoSuchElementException("Building not found"));}
}
